function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(71501);
var T0=Date.now();/*Signature edition*/
var E=5,Q=50;
var nodes=[];for(var i=0;i<E;i++)nodes.push({bat:20+Math.floor(R()*80),lat:5+Math.floor(R()*60),cap:Math.ceil(Q/E)+3});
var served=0,latSum=0,dropped=0;
for(var q=0;q<Q;q++){
  var feas=nodes.filter(function(n){return n.cap>0&&n.bat>10;}).sort(function(a,b){return a.lat-b.lat;});
  if(!feas.length){dropped++;continue;}
  var n=feas[0];n.cap--;n.bat-=2;served++;latSum+=n.lat;
}
console.log(JSON.stringify({id:"JAH-APX71S-000001",ok:true,metrics:{edge_nodes:E,requests:Q,served:served,dropped:dropped,serve_rate_pct:+(100*served/Q).toFixed(1),avg_latency_ms:served?+(latSum/served).toFixed(1):null},ms:Date.now()-T0}));

